'use strict';
const FX=FlowerExperience;
let favorites=new Set(),onlyFavorites=false,finderStep=0;
let intent=FX.sanitizeIntent(),intentChosen=false;
try{const raw=JSON.parse(localStorage.getItem('bierbach-favorites-v1')||'[]');if(Array.isArray(raw))favorites=new Set(raw.filter(x=>typeof x==='string').slice(0,100));const stored=JSON.parse(sessionStorage.getItem('bierbach-intent-v1')||'null');if(stored){intent=FX.sanitizeIntent(stored);intentChosen=true;}}catch{}
const urlPrefs=new URLSearchParams(location.search);
if(urlPrefs.has('anlass')||urlPrefs.has('stil')){const mood=Object.keys(FX.styles).find(k=>FX.styles[k].category===urlPrefs.get('stil'))||intent.mood;intent=FX.sanitizeIntent({...intent,occasion:urlPrefs.get('anlass')||intent.occasion,mood,budget:urlPrefs.get('budget')||intent.budget});intentChosen=true;persistIntent();}
const finderDialog=$('#finder-dialog');
function persistIntent(){if(!intentChosen)return;try{sessionStorage.setItem('bierbach-intent-v1',JSON.stringify(intent));}catch{}}
function showFinder(){if(!config){toast('Die Blumenideen werden geladen. Bitte gleich erneut versuchen.');return;}finderStep=0;renderFinder();finderDialog.showModal();}
function finderTitle(){return ['Für welchen Moment?','Welche Farben fühlen sich richtig an?','Wie viel möchten Sie schenken?','Ihre Blumenrichtung.'][finderStep];}
function renderFinder(){const style=FX.styles[intent.mood];const root=$('#finder-content');const botanical='<svg class="finder-botanical" viewBox="0 0 180 240" aria-hidden="true"><path d="M90 230C80 175 125 120 88 20M89 198C35 195 27 152 45 140C70 143 92 169 89 198M96 155C146 153 165 111 146 98C120 102 100 124 96 155M97 105C45 96 39 59 56 51C78 58 97 77 97 105M90 61C125 49 133 19 117 9C97 20 89 35 90 61"/></svg>';
root.innerHTML=`<div class="finder-side"><p class="eyebrow">Ihr kleiner Blumenkompass</p><h2>Ein Gefühl.<br><em>Ein passender Strauß.</em></h2><p>Drei kleine Entscheidungen.<br>Eine persönliche Blumenidee.</p>${botanical}<span class="finder-side-note">Persönlich gebunden.<br>Nach Ihren Wünschen.</span></div><div class="finder-main"><div class="finder-progress" aria-label="Schritt ${Math.min(finderStep+1,3)} von 3">${[0,1,2].map(i=>`<span class="${finderStep>=i?'done':''}"></span>`).join('')}<small>${finderStep===3?'Ihre Inspiration':String(finderStep+1).padStart(2,'0')+' / 03'}</small></div><p class="eyebrow">${['Der Anlass','Die Farbstimmung','Ihr Wunschbudget','Für Sie ausgewählt'][finderStep]}</p><h2 id="finder-title" tabindex="-1">${finderTitle()}</h2><div class="finder-stage">${finderStep===0?`<div class="finder-options">${[['Geburtstag','✷'],['Danke','♡'],['Liebe','♥'],['Einfach so','✳'],['Gute Besserung','☀'],['Jubiläum','✧']].map(([label,icon])=>`<button class="finder-option ${intent.occasion===label?'chosen':''}" data-occasion="${label}" aria-pressed="${intent.occasion===label}"><span>${icon}</span>${label}</button>`).join('')}</div>`:finderStep===1?`<div class="mood-options">${Object.entries(FX.styles).map(([key,s])=>`<button class="mood-option ${intent.mood===key?'chosen':''}" data-mood="${key}" aria-pressed="${intent.mood===key}"><span class="mood-swatches ${key}" aria-hidden="true"><i></i><i></i><i></i></span><strong>${s.label}</strong><span class="mood-check">${intent.mood===key?'✓':'○'}</span></button>`).join('')}</div><p class="small">Eine Farbrichtung, kein festgelegtes Rezept. Saisonale Blumen stimmen wir mit Ihnen ab.</p>`:finderStep===2?`<div class="budget-presets">${[30,45,60].map(n=>`<button data-budget="${n}" class="${intent.budget===n?'chosen':''}" aria-pressed="${intent.budget===n}">${n} €</button>`).join('')}</div><label>Oder Ihr eigener Betrag (€)<input id="finder-budget" type="number" min="1" max="10000" step="0.01" value="${intent.budget}" inputmode="decimal" required></label><p class="small">Wunschbudget pro Strauß, kein bestätigter Verkaufspreis. Grußkarte und Lieferung kommen bei Auswahl dazu.</p><div class="finder-budget-note"><span>Ihre Richtung</span><strong>${esc(intent.occasion)} · ${esc(style.label)}</strong></div>`:`<p class="finder-result-intro">${esc(intent.occasion)} · ${esc(style.label)}<br><strong>${CartCore.money(Math.round(intent.budget*100))}</strong> Wunschbudget pro Strauß</p><div class="finder-results">${FX.recommend(config.products,intent.mood).map(p=>`<a href="${catalogLink(p.id)}"><img src="assets/${p.image}.webp" alt="${esc(p.name)}" width="200" height="230"><span>${esc(p.name)} ↗</span></a>`).join('')}</div><p class="small">Inspirationen nach Ihrer Farbrichtung. Verfügbarkeit, Blumen und endgültigen Preis bestätigen wir persönlich.</p>`}</div><div class="finder-footer">${finderStep>0?'<button class="underlink" data-finder-back>← Zurück</button>':'<button class="underlink" data-finder-reset>Auswahl zurücksetzen</button>'}${finderStep<3?`<button class="button" data-finder-next>${finderStep===2?'Meine Blumenideen':'Weiter'} →</button>`:`<a class="button" href="${catalogLink()}">Auswahl übernehmen ↗</a>`}</div></div>`;
$$('[data-occasion]',root).forEach(b=>b.addEventListener('click',()=>{intent.occasion=b.dataset.occasion;persistIntent();$$('[data-occasion]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b));});}));
$$('[data-mood]',root).forEach(b=>b.addEventListener('click',()=>{intent.mood=b.dataset.mood;persistIntent();renderFinder();}));
$$('[data-budget]',root).forEach(b=>b.addEventListener('click',()=>{intent.budget=Number(b.dataset.budget);$('#finder-budget').value=intent.budget;$$('[data-budget]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b));});}));
$('#finder-budget',root)?.addEventListener('input',()=>{$$('[data-budget]').forEach(x=>{const selected=Number(x.dataset.budget)===Number($('#finder-budget').value);x.classList.toggle('chosen',selected);x.setAttribute('aria-pressed',String(selected));});});
$('[data-finder-next]',root)?.addEventListener('click',()=>{if(finderStep===2){const input=$('#finder-budget');if(!input.reportValidity())return;intent.budget=Number(input.value);intentChosen=true;persistIntent();}finderStep++;renderFinder();$('#finder-title').focus({preventScroll:true});});$('[data-finder-back]',root)?.addEventListener('click',()=>{finderStep--;renderFinder();$('#finder-title').focus({preventScroll:true});});$('[data-finder-reset]',root)?.addEventListener('click',()=>{intent=FX.sanitizeIntent();intentChosen=false;try{sessionStorage.removeItem('bierbach-intent-v1');}catch{}renderFinder();});
}
function catalogLink(id){const s=FX.styles[intent.mood];const params=new URLSearchParams({anlass:intent.occasion,stil:s.category,budget:String(intent.budget)});if(id)params.set('idee',id);return 'floristik.html?'+params.toString()+(id?'#idee-'+id:'');}
function updateFavoriteUI(){const total=config?config.products.filter(p=>favorites.has(p.id)).length:favorites.size;$$('[data-favorite-count]').forEach(el=>el.textContent=total);$$('[data-favorite]').forEach(b=>{const p=config?.products.find(x=>x.id===b.dataset.favorite);const yes=favorites.has(b.dataset.favorite);b.classList.toggle('is-favorite',yes);b.setAttribute('aria-pressed',String(yes));b.setAttribute('aria-label',(p?.name||'Blumenidee')+(yes?' aus Favoriten entfernen':' merken'));b.textContent=yes?'♥':'♡';});}
function applyCatalogFilters(){if(!config)return;if(!$('[data-products="all"]'))return;const category=$('[data-filter].active')?.dataset.filter||'all';const query=($('#catalog-search')?.value||'').toLocaleLowerCase('de');let visible=0;$$('[data-category]').forEach(el=>{const p=config.products.find(x=>x.id===el.dataset.productId);const match=(category==='all'||p.category===category||p.id==='wunschstrauss')&&(!onlyFavorites||favorites.has(p.id))&&(!query||(p.name+' '+p.description+' '+p.category).toLocaleLowerCase('de').includes(query));el.hidden=!match;if(match)visible++;});$('#empty-products').hidden=visible>0;observeReveals();}
function animateAdded(button){if(reducedMotion())return;button.classList.remove('just-added');void button.offsetWidth;button.classList.add('just-added');$('.cart-toggle')?.classList.add('basket-pulse');setTimeout(()=>{button.classList.remove('just-added');$('.cart-toggle')?.classList.remove('basket-pulse');},750);}
const baseRenderProducts=renderProducts;
renderProducts=function(){baseRenderProducts();$$('[data-category]').forEach(el=>{const form=$('.product-form',el);const id=form.dataset.productId;el.dataset.productId=id;el.id='idee-'+id;const heart=document.createElement('button');heart.className='favorite-heart';heart.type='button';heart.dataset.favorite=id;el.prepend(heart);heart.addEventListener('click',()=>{if(favorites.has(id))favorites.delete(id);else favorites.add(id);try{localStorage.setItem('bierbach-favorites-v1',JSON.stringify([...favorites]));}catch{}updateFavoriteUI();applyCatalogFilters();toast(favorites.has(id)?'Für später gemerkt.':'Aus Favoriten entfernt.');});if(intentChosen){const budget=$('[name="budget"]',form),color=$('[name="color"]',form);if(budget)budget.value=intent.budget;if(color)color.value=FX.styles[intent.mood].color;}form.addEventListener('submit',()=>{if(form.checkValidity())animateAdded($('.add-button',form));});});updateFavoriteUI();if(intentChosen&&$('[data-products="all"]')){const category=FX.styles[intent.mood].category;$$('[data-filter]').forEach(b=>{const yes=b.dataset.filter===category;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',String(yes));});$('#selection-context').hidden=false;$('#selection-context').innerHTML=`<span>Ihre Richtung: <strong>${esc(intent.occasion)} · ${esc(FX.styles[intent.mood].label)}</strong> · ${CartCore.money(Math.round(intent.budget*100))} Wunschbudget</span><button class="underlink" data-finder-open>Ändern ↗</button>`;}
applyCatalogFilters();revealImages();if(urlPrefs.get('idee'))requestAnimationFrame(()=>$('#idee-'+CSS.escape(urlPrefs.get('idee')))?.scrollIntoView({block:'center',behavior:reducedMotion()?'instant':'smooth'}));};
const baseUpdateCount=updateCount;updateCount=function(){baseUpdateCount();const count=cart.reduce((s,x)=>s+x.quantity,0);$$('[data-mobile-summary]').forEach(el=>el.textContent=count?count+' Blumenidee'+(count===1?'':'n')+' für Ihren Moment':'Eine Idee für einen lieben Menschen?');};
const baseRenderCart=renderCart;
renderCart=function(){if(intentChosen){if(!details.occasion)details.occasion=intent.occasion;if(!details.date&&intent.date>=localDate())details.date=intent.date;}baseRenderCart();const form=$('#request-form');if(!form)return;
const cardArea=$('[data-show-card]',form);cardArea.insertAdjacentHTML('beforeend',`<div class="greeting-suggestions" role="group" aria-label="Textideen für die Grußkarte"><button type="button" data-greeting="Alles Liebe zum Geburtstag!">Geburtstag</button><button type="button" data-greeting="Ein kleines Dankeschön von Herzen.">Danke</button><button type="button" data-greeting="Einfach, weil es dich gibt.">Einfach so</button></div><div class="greeting-preview"><span class="greeting-flower" aria-hidden="true">✳</span><p data-greeting-preview></p><span class="greeting-signature">Ein Blumengruß von Herzen.</span></div><p class="small">Textvorschau · Das Kartenmotiv stimmen wir persönlich ab.</p>`);
const date=$('[name="date"]',form);date.closest('label').insertAdjacentHTML('beforebegin',`<div class="quick-dates" role="group" aria-label="Wunschdatum schnell wählen"><button type="button" data-quick-date="${localDate()}">Heute anfragen</button><button type="button" data-quick-date="${FX.dateAfter(localDate(),1)}">Morgen anfragen</button><button type="button" data-date-focus>Anderes Datum ↗</button></div><p class="small">Ein Terminwunsch — keine Zusage. Wir bestätigen die Möglichkeit persönlich.</p>`);
form.querySelector('fieldset:last-of-type legend').insertAdjacentHTML('afterend',`<label>Anlass <span class="optional">optional</span><select name="occasion"><option value="">Bitte wählen</option>${['Geburtstag','Danke','Liebe','Einfach so','Gute Besserung','Jubiläum'].map(o=>`<option ${details.occasion===o?'selected':''}>${o}</option>`).join('')}</select></label>`);
form.querySelector('fieldset:last-of-type').insertAdjacentHTML('beforeend',`<label class="check-row photo-request"><input type="checkbox" name="photoRequest" ${details.photoRequest?'checked':''}><span>Ein Foto vor der Übergabe anfragen<small>Als zusätzlicher Wunsch, nach Absprache mit dem Geschäft.</small></span></label>`);
$$('[data-greeting]',form).forEach(b=>b.addEventListener('click',()=>{$('[name="cardText"]').value=b.dataset.greeting;$('[name="cardText"]').dispatchEvent(new Event('input',{bubbles:true}));}));$$('[data-quick-date]',form).forEach(b=>b.addEventListener('click',()=>{date.value=b.dataset.quickDate;date.dispatchEvent(new Event('input',{bubbles:true}));}));$('[data-date-focus]',form).addEventListener('click',()=>{date.focus();try{date.showPicker();}catch{}});updateFormState();};
const baseUpdateFormState=updateFormState;
updateFormState=function(){baseUpdateFormState();const preview=$('[data-greeting-preview]');if(preview){preview.textContent=$('[name="cardText"]').value.trim()||'Ihre persönlichen Worte stehen hier.';preview.classList.toggle('placeholder',!$('[name="cardText"]').value.trim());}$$('[data-quick-date]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.quickDate===$('[name="date"]')?.value)));};
document.addEventListener('click',e=>{if(e.target.closest('[data-finder-open]'))showFinder();if(e.target.closest('[data-filter]'))applyCatalogFilters();});
$('#catalog-search')?.addEventListener('input',applyCatalogFilters);$('#favorite-filter')?.addEventListener('click',()=>{onlyFavorites=!onlyFavorites;$('#favorite-filter').setAttribute('aria-pressed',String(onlyFavorites));applyCatalogFilters();});$('#reset-catalog')?.addEventListener('click',()=>{onlyFavorites=false;$('#favorite-filter').setAttribute('aria-pressed','false');$('#catalog-search').value='';$('[data-filter="all"]').click();});
finderDialog.addEventListener('click',e=>{if(e.target===finderDialog){const r=finderDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)finderDialog.close();}});
function revealImages(){$$('img[src]').forEach(img=>{if(img.complete)return;img.classList.add('image-arriving');const done=()=>img.classList.remove('image-arriving');img.addEventListener('load',done,{once:true});img.addEventListener('error',done,{once:true});});}
try{if(!sessionStorage.getItem('bierbach-welcomed-v2')){document.body.classList.add('first-visit');sessionStorage.setItem('bierbach-welcomed-v2','1');}}catch{}document.body.classList.add('experience-ready');revealImages();
if(config){renderProducts();updateCount();}
const heroVisual=$('.hero-visual');
if(heroVisual&&matchMedia('(hover:hover) and (pointer:fine)').matches){let frame=0;heroVisual.addEventListener('pointermove',e=>{if(reducedMotion()||frame)return;frame=requestAnimationFrame(()=>{const r=heroVisual.getBoundingClientRect();heroVisual.style.setProperty('--flower-x',((e.clientX-r.left)/r.width-.5)*-8+'px');heroVisual.style.setProperty('--flower-y',((e.clientY-r.top)/r.height-.5)*-8+'px');frame=0;});},{passive:true});heroVisual.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);frame=0;heroVisual.style.setProperty('--flower-x','0px');heroVisual.style.setProperty('--flower-y','0px');});}
